//! C-alignment regression tests (step 5h, SQL-level behaviour). GENERATED by
//! target/perf-work/step5h/gen/gen_tests5h.py: every expected line is what the C SQLite 3.54.1 shell prints in
//! list mode for the same statements (an error is reduced to `ERR: <message>`).
use crate::Connection;
use sqliters_types::Value;

fn render(v: &Value) -> String {
    match v {
        Value::Null => String::new(),
        Value::Integer(i) => i.to_string(),
        Value::Text(s) => s.split('\0').next().unwrap_or("").to_owned(),
        Value::Blob(b) => String::from_utf8_lossy(b).into_owned(),
        Value::Real(r) => sqliters_types::real_to_text(*r),
    }
}

/// Runs every statement list; a failing statement ends its list with `ERR: message`.
fn run(pre: Option<&str>, stmts: &[&str]) -> Vec<String> {
    let conn = Connection::open_in_memory().unwrap();
    if let Some(p) = pre {
        conn.execute(p).unwrap();
    }
    let mut out = Vec::new();
    for line in stmts {
        let mut rest: &str = line;
        loop {
            let trimmed = rest.trim_start();
            if trimmed.is_empty() {
                break;
            }
            let mut stmt = match conn.prepare(trimmed) {
                Ok(s) => s,
                Err(e) => {
                    out.push(format!("ERR: {}", e.message));
                    break;
                }
            };
            let tail_len = stmt.tail().len();
            let mut failed = false;
            loop {
                match stmt.step() {
                    Ok(crate::StepResult::Row(r)) => {
                        out.push(r.values().iter().map(render).collect::<Vec<_>>().join("|"))
                    }
                    Ok(_) => break,
                    Err(e) => {
                        out.push(format!("ERR: {}", e.message));
                        failed = true;
                        break;
                    }
                }
            }
            if let Err(e) = stmt.finalize()
                && !failed
            {
                out.push(format!("ERR: {}", e.message));
                failed = true;
            }
            if failed || tail_len == 0 || tail_len >= trimmed.len() {
                break;
            }
            rest = &trimmed[trimmed.len() - tail_len..];
        }
    }
    out
}

#[test]
fn a_real_to_text() {
    let got = run(
        None,
        &[
            "SELECT 1e15, 1e16, 1e17, 1e100, 1e-5, 2.0/3, 4611686018427387904.0, 0.1+0.2, 49.47, 5e-324, -0.0",
            "SELECT CAST(1e16 AS TEXT), 1e100||'', quote(1e-5), printf('%s',2.0/3), format('%s|%s',1e15,1.5)",
            "SELECT quote(9e999), quote(-9e999), CAST(9e999 AS TEXT), json_array(1e16, 0.1+0.2, 1e100)",
            "SELECT json_quote(2.0/3), json_object('a',1e-5), group_concat(x) FROM (SELECT 1e15 AS x UNION ALL SELECT 2.5e-7)",
            "CREATE TABLE t(x TEXT, y); INSERT INTO t VALUES(1e15,1e15),(1e100,1e100),(1e-5,1e-5)",
            "SELECT x, typeof(x), y, typeof(y) FROM t",
            "SELECT CAST('3500000000000000.2500001' AS REAL), 3500000000000000.2500001, CAST('1e400' AS REAL), CAST('  12.5abc' AS REAL)",
            "SELECT '9223372036854775808'+0, typeof('12abc'+0), '1e3'+0, typeof('0x10'+0), CAST('-9223372036854775809' AS INTEGER)",
        ],
    );
    let want: &[&str] = &[
        "1000000000000000.0|10000000000000000.0|1.0e+17|1.0e+100|1.0e-05|0.66666666666666663|4.6116860184273879e+18|0.30000000000000004|49.47|4.9406564584124654e-324|0.0",
        "10000000000000000.0|1.0e+100|1.0e-05|0.66666666666666663|1000000000000000.0|1.5",
        "9.0e+999|-9.0e+999|Inf|[10000000000000000.0,0.30000000000000004,1.0e+100]",
        "0.66666666666666663|{\"a\":1.0e-05}|1000000000000000.0,2.5e-07",
        "1000000000000000.0|text|1000000000000000.0|real",
        "1.0e+100|text|1.0e+100|real",
        "1.0e-05|text|1.0e-05|real",
        "3500000000000000.0|3500000000000000.0|Inf|12.5",
        "9.2233720368547758e+18|integer|1000.0|integer|-9223372036854775808",
    ];
    assert_eq!(got, want);
}

#[test]
fn a_printf() {
    let got = run(
        None,
        &[
            "SELECT printf('%d|%5d|%-5d|%05d|%+d|%,d', 42,42,42,42,42,1234567)",
            "SELECT printf('%f|%.2f|%10.3f|%-10.1f|%e|%g',1.5,2.345,3.14159,2.25,12345.678,0.0001)",
            "SELECT printf('%g|%G|%!g|%#g|%.17g|%!.17g|%.20e',1e20,1e-10,2.0,2.0,0.1,0.1,0.1)",
            "SELECT printf('%s|%5s|%-5s|%.2s|%q|%Q|%w|%c|%r|%r','ab','ab','ab','abc','it''s','it''s','a\"b','xyz',3,11)",
            "SELECT printf('%Q|%q|%s|%d|%x|%X|%#o|%u',NULL,NULL,NULL,NULL,255,255,8,-1), printf(), format(NULL)",
            "SELECT printf('%!0.17g|%010.2f|%,.2f|%5%|%y|z',9e999,-1.5,1234567.891)",
        ],
    );
    let want: &[&str] = &[
        "42|   42|42   |00042|+42|1,234,567",
        "1.500000|2.35|     3.142|2.3       |1.234568e+04|0.0001",
        "1e+20|1E-10|2.0|2.00000|0.1|0.1|1.00000000000000000000e-01",
        "ab|   ab|ab   |ab|it''s|'it''s'|a\"\"b|x|3rd|11th",
        "NULL|(NULL)||0|ff|FF|010|18446744073709551615||",
        "9.0e+999|-000001.50|1,234,567.89|    %|",
    ];
    assert_eq!(got, want);
}

#[test]
fn b_functions() {
    let got = run(
        None,
        &[
            "SELECT quote(substr('NEW',-6)), quote(substr('hello',0,3)), quote(substr('hello',-3,2)), quote(substr('hello',4,-2)), quote(substr(x'01020304',2,2)), quote(substr(x'',1))",
            "SELECT hex(NULL) IS '', hex(12), hex('a'), quote(unhex(10,'1.0')), quote(unhex(x'00')), unicode(x'00') IS NULL, quote(char(65,NULL,-1))",
            "SELECT quote(min(0.0,0,x'01')), quote(max(0,0.0)), ln(0) IS NULL, log(255,'+1 day'), log(0.5,9) IS NULL, round(' 12 ',1e16), round(1.005,2), round(2.5)",
            "SELECT concat('a',NULL,1), concat_ws('-','a',NULL,1), unistr('a\\0041\\u00e9'), unistr_quote('a'||char(10)||'b'), instr(x'010203',x'03'), like(x'00',x'')",
            "SELECT concat()",
            "SELECT like('a','b',char(0))",
            "CREATE TABLE d(x); INSERT INTO d VALUES(1),(1.0),('1'),(2),(2.5),(NULL),(0),(0.0)",
            "SELECT count(DISTINCT x), sum(DISTINCT x), group_concat(DISTINCT x), typeof(sum(DISTINCT x)) FROM d",
            "SELECT value FROM generate_series(1,5) WHERE value < '2'",
            "SELECT value FROM generate_series(1,9) WHERE value > 2.2 AND value < '7.5'",
            "SELECT value FROM generate_series(1,5) WHERE value BETWEEN '2' AND '4'",
            "SELECT value FROM generate_series(50,1,-7) WHERE value > 10 AND value <= 43",
            "SELECT json_insert(), json_set() IS NULL, hex(jsonb_array('a','q\"x',char(10))), json_group_object(x'00',1)",
            "SELECT json_insert('[1]','$[#]')",
            "SELECT json_set('{}','x',1)",
            "SELECT json_object('a',x'61',1,2)",
        ],
    );
    let want: &[&str] = &[
        "'NEW'|'he'|'ll'|'el'|X'0203'|NULL",
        "1|3132|61|X'10'|X''|1|'A'",
        "0|0|1|0.0|1|12.0|1.0|3.0",
        "a1|a-1|aAé|unistr('a\\u000ab')|3|1",
        "ERR: wrong number of arguments to function concat()",
        "ERR: ESCAPE expression must be a single character",
        "5|6.5|1,1,2,2.5,0|real",
        "1",
        "3",
        "4",
        "5",
        "6",
        "7",
        "2",
        "3",
        "4",
        "43",
        "36",
        "29",
        "22",
        "15",
        "|1|AB176148715C2278285C6E|{\"\":1}",
        "ERR: json_insert() needs an odd number of arguments",
        "ERR: bad JSON path: 'x'",
        "ERR: json_object() labels must be TEXT",
    ];
    assert_eq!(got, want);
}

#[test]
fn b_utf16() {
    let got = run(
        Some("PRAGMA encoding='UTF-16le'"),
        &[
            "CREATE TABLE u(v); INSERT INTO u VALUES('abc'),(12),(x'6100')",
            "SELECT hex(v), octet_length(v), length(v) FROM u",
            "SELECT hex('a'), octet_length('ab'), octet_length(-1), lower(x'4100'), unicode(x'4100')",
        ],
    );
    let want: &[&str] = &["610062006300|6|3", "3132|4|2", "6100|2|2", "6100|4|4|a|65"];
    assert_eq!(got, want);
}

#[test]
fn c_rowid_and_vtab() {
    let got = run(
        None,
        &[
            "CREATE TABLE t(a); INSERT INTO t(rowid,a) VALUES(9223372036854775807,'m'); INSERT INTO t(a) VALUES('x'),('y')",
            "SELECT count(*), min(rowid)>0, max(rowid) FROM t",
            "CREATE TABLE u(id INTEGER PRIMARY KEY AUTOINCREMENT, a); INSERT INTO u VALUES(9223372036854775807,'m')",
            "INSERT INTO u(a) VALUES('x')",
            "CREATE VIRTUAL TABLE rt USING rtree(id,x0,x1); INSERT INTO rt VALUES(9223372036854775807,1,2); INSERT INTO rt(x0,x1) VALUES(3,4),(5,6)",
            "SELECT count(*), min(id)>0, max(id) FROM rt",
            "CREATE VIRTUAL TABLE r2 USING rtree(id,x0,x1); INSERT INTO r2 VALUES(1,1,2)",
            "INSERT OR FAIL INTO r2 VALUES(5,1,2),(2,3,4),(1,5,6),(3,7,8)",
            "SELECT group_concat(id) FROM (SELECT id FROM r2 ORDER BY id)",
            "SELECT changes()",
        ],
    );
    let want: &[&str] = &[
        "3|1|9223372036854775807",
        "ERR: database or disk is full",
        "3|1|9223372036854775807",
        "ERR: UNIQUE constraint failed: r2.id",
        "1,2,5",
        "2",
    ];
    assert_eq!(got, want);
}

#[test]
fn c_ctas_defaults() {
    let got = run(
        None,
        &[
            "CREATE TABLE a(x); CREATE TABLE x1 AS SELECT type,name,tbl_name,rootpage,sql FROM sqlite_schema",
            "SELECT quote(type),quote(name),quote(tbl_name),quote(rootpage),quote(sql) FROM x1",
            "CREATE TABLE d(a, b DEFAULT x'00ff', c DEFAULT (1 + 2), d DEFAULT 5., e TEXT DEFAULT 5., f DEFAULT 'it''s', h DEFAULT +2.50, i DEFAULT (  abs(-3)  ), l DEFAULT \"dq\", m DEFAULT 0x10, o DEFAULT TRUE, q DEFAULT 1e3)",
            "SELECT name, quote(dflt_value) FROM pragma_table_info('d')",
            "CREATE TABLE e(a); INSERT INTO e VALUES(1); ALTER TABLE e ADD COLUMN b TEXT DEFAULT 5.; ALTER TABLE e ADD COLUMN c TEXT DEFAULT 1e3; ALTER TABLE e ADD COLUMN f TEXT DEFAULT +7.50; ALTER TABLE e ADD COLUMN i TEXT DEFAULT -0.0; ALTER TABLE e ADD COLUMN g INT DEFAULT 5.; INSERT INTO e(a) VALUES(2)",
            "SELECT a, quote(b), quote(c), quote(f), quote(i), quote(g) FROM e",
        ],
    );
    let want: &[&str] = &[
        "'table'|'a'|'a'|2|'CREATE TABLE a(x)'",
        "NULL|NULL|NULL|NULL|NULL",
        "a|NULL",
        "b|'x''00ff'''",
        "c|'1 + 2'",
        "d|'5.'",
        "e|'5.'",
        "f|'''it''''s'''",
        "h|'+2.50'",
        "i|'abs(-3)'",
        "l|'\"dq\"'",
        "m|'0x10'",
        "o|'TRUE'",
        "q|'1e3'",
        "1|'5.'|'1e3'|'7.50'|'-0.0'|5",
        "2|'5.0'|'1000.0'|'7.5'|'0.0'|5",
    ];
    assert_eq!(got, want);
}

#[test]
fn c_generated_checks() {
    let got = run(
        None,
        &[
            "CREATE TABLE g1(a, b AS (random()))",
            "CREATE TABLE g2(a, b AS (rowid+1))",
            "CREATE TABLE g4(a, b AS (c), c AS (b))",
            "CREATE TABLE g5(a, b AS (c), c AS (b), d AS (b))",
            "CREATE TABLE g6(a, b AS (abs(a)) STORED PRIMARY KEY)",
            "CREATE TABLE g7(a, b AS (a) DEFAULT 5)",
            "CREATE TABLE g7b(a, b DEFAULT 5 AS (a))",
            "CREATE TABLE g8(a, b AS ((SELECT 1)))",
            "CREATE TABLE g11(a, b AS (changes()))",
            "CREATE TABLE g15(a, b AS (?1))",
            "CREATE TABLE g17(a, b AS (current_timestamp))",
            "CREATE TABLE g21(a, b AS (g21.a))",
            "CREATE TABLE ok1(a, b AS (datetime(a)), c AS (a+1) STORED, d AS (c*2))",
            "CREATE TABLE h(a); ALTER TABLE h ADD COLUMN b AS (random())",
            "ALTER TABLE h ADD COLUMN c AS (rowid)",
            "ALTER TABLE h ADD COLUMN j AS ((SELECT 1))",
            "SELECT group_concat(name) FROM (SELECT name FROM sqlite_schema ORDER BY name)",
            "CREATE TABLE y8(x); INSERT INTO y8 VALUES(1); ALTER TABLE y8 ADD COLUMN y INT CHECK(y>0) DEFAULT -1",
        ],
    );
    let want: &[&str] = &[
        "ERR: non-deterministic functions prohibited in generated columns",
        "ERR: no such column: rowid",
        "ERR: generated column loop on \"c\"",
        "ERR: generated column loop on \"b\"",
        "ERR: generated columns cannot be part of the PRIMARY KEY",
        "ERR: cannot use DEFAULT on a generated column",
        "ERR: error in generated column \"b\"",
        "ERR: subqueries prohibited in generated columns",
        "ERR: non-deterministic functions prohibited in generated columns",
        "ERR: parameters prohibited in generated columns",
        "ERR: non-deterministic functions prohibited in generated columns",
        "ERR: the \".\" operator prohibited in generated columns",
        "ERR: error in table h after add column: non-deterministic functions prohibited in generated columns",
        "ERR: error in table h after add column: no such column: rowid",
        "ERR: error in table h after add column: subqueries prohibited in generated columns",
        "h,ok1",
        "ERR: CHECK constraint failed",
    ];
    assert_eq!(got, want);
}

#[test]
fn d_group_order() {
    let got = run(
        None,
        &[
            "CREATE TABLE g(k, v, w TEXT COLLATE NOCASE, n INT); INSERT INTO g VALUES('b',1,'B',3),('a',2,'a',1),('c',3,'A',2),('b',4,'b',3),(NULL,5,'C',NULL),('a',6,'c',1),(2,7,'z',9),(1.0,8,'Z',9),(1,9,'m',8),(x'00',10,'M',7),('B',11,'k',6)",
            "SELECT k, sum(v) FROM g GROUP BY k",
            "SELECT k, count(*) FROM g WHERE v>1 GROUP BY k",
            "SELECT w, count(*), min(v) FROM g GROUP BY w",
            "SELECT n, sum(v) FROM g GROUP BY n",
            "CREATE INDEX gn ON g(n DESC)",
            "SELECT n, sum(v) FROM g GROUP BY n",
            "CREATE TABLE h(id INTEGER PRIMARY KEY, k, x); INSERT INTO h VALUES(1,'b',10),(2,'a',20),(3,'c',30)",
            "SELECT g.k, sum(h.x), count(*) FROM g JOIN h ON g.k=h.k GROUP BY g.k",
        ],
    );
    let want: &[&str] = &[
        "|5", "1.0|17", "2|7", "B|11", "a|8", "b|5", "c|3", "␀|10", "|1", "1.0|2", "2|1", "B|1",
        "a|2", "b|1", "c|1", "␀|1", "a|2|2", "B|2|1", "C|2|5", "k|1|11", "m|2|9", "z|2|7", "|5",
        "1|8", "2|3", "3|5", "6|11", "7|10", "8|9", "9|15", "9|15", "8|9", "7|10", "6|11", "3|5",
        "2|3", "1|8", "|5", "a|40|2", "b|20|2", "c|30|1",
    ];
    assert_eq!(got, want);
}

#[test]
fn h_fts5() {
    let got = run(
        None,
        &[
            "CREATE VIRTUAL TABLE f USING fts5(a); INSERT INTO f VALUES('hello world'),('other')",
            "SELECT highlight(f,0,'[',']') FROM f WHERE f MATCH 'hello'",
        ],
    );
    let want: &[&str] = &["[hello] world"];
    assert_eq!(got, want);
}

struct TempDb(std::path::PathBuf);

impl TempDb {
    fn new(name: &str) -> Self {
        let path =
            std::env::temp_dir().join(format!("sqliters-5h-{}-{name}.db", std::process::id()));
        let _ = std::fs::remove_file(&path);
        Self(path)
    }
}

impl Drop for TempDb {
    fn drop(&mut self) {
        let _ = std::fs::remove_file(&self.0);
    }
}

fn check_rows(db: &TempDb, sql: &str) -> Vec<String> {
    let conn = Connection::open(&db.0).unwrap();
    conn.query(sql, &[])
        .unwrap()
        .rows
        .iter()
        .map(|r| r.values().iter().map(render).collect::<Vec<_>>().join("|"))
        .collect()
}

// The two files are built the way the C-made originals were (index definitions swapped through
// writable_schema); the expected rows are what C `PRAGMA integrity_check` prints for them.
#[test]
fn e_integrity_values_differ_from_index() {
    let db = TempDb::new("ic17");
    {
        let conn = Connection::open(&db.0).unwrap();
        conn.execute(
            "CREATE TABLE t(a TEXT COLLATE NOCASE, b); CREATE INDEX i ON t(a);
             INSERT INTO t VALUES('ABC',1),('def',2),('Xyz',3);
             PRAGMA writable_schema=ON;
             UPDATE sqlite_master SET sql='CREATE INDEX i ON t(b)' WHERE name='i';",
        )
        .unwrap();
    }
    {
        let conn = Connection::open(&db.0).unwrap();
        conn.execute(
            "UPDATE t SET a='abc' WHERE rowid=1; UPDATE t SET a='XYZ' WHERE rowid=3;
             PRAGMA writable_schema=ON;
             UPDATE sqlite_master SET sql='CREATE INDEX i ON t(a)' WHERE name='i';",
        )
        .unwrap();
    }
    assert_eq!(
        check_rows(&db, "PRAGMA integrity_check"),
        [
            "row 1 values differ from index i",
            "row 3 values differ from index i"
        ]
    );
    assert_eq!(check_rows(&db, "PRAGMA quick_check"), ["ok"]);
    assert_eq!(
        check_rows(&db, "PRAGMA integrity_check(1)"),
        ["row 1 values differ from index i"]
    );
}

#[test]
fn e_integrity_rowid_not_at_end_of_record() {
    let db = TempDb::new("ic16");
    {
        let conn = Connection::open(&db.0).unwrap();
        conn.execute(
            "CREATE TABLE t1(a); CREATE TABLE t2(a,b);
             INSERT INTO t1(rowid,a) VALUES(1,'x'),(2,'y'),(3,'z');
             INSERT INTO t2(rowid,a,b) VALUES(11,'x',1),(12,'y',2),(3,'z',3);
             CREATE INDEX i ON t2(a,b);
             PRAGMA writable_schema=ON;
             UPDATE sqlite_master SET tbl_name='t1', sql='CREATE INDEX i ON t1(a)' WHERE name='i';",
        )
        .unwrap();
    }
    assert_eq!(
        check_rows(&db, "PRAGMA integrity_check"),
        [
            "rowid not at end-of-record for row 1 of index i",
            "rowid not at end-of-record for row 2 of index i"
        ]
    );
    assert_eq!(check_rows(&db, "PRAGMA quick_check"), ["ok"]);
}

// C refuses an FTS5 table whose %_config version is neither 4 nor 5 when it connects to it.
#[test]
fn h_fts5_config_version_is_checked_at_connect() {
    let db = TempDb::new("fts5ver");
    {
        let conn = Connection::open(&db.0).unwrap();
        conn.execute(
            "CREATE VIRTUAL TABLE f USING fts5(a); INSERT INTO f VALUES('hello');
             UPDATE f_config SET v=99 WHERE k='version';",
        )
        .unwrap();
    }
    let conn = Connection::open(&db.0).unwrap();
    let err = conn.query("SELECT * FROM f", &[]).unwrap_err();
    assert_eq!(
        err.message,
        "invalid fts5 file format (found 99, expected 4 or 5) - run 'rebuild'"
    );
}
